def transform(nums):
    result = []
    for n in nums:
        if n < 0:
            continue
        if n % 2 == 0:
            result.append(n // 2)
        else:
            result.append(n * 3 + 1)
    return result

print(transform([-2, 0, 3, 4]))
```

